{
  "name": "@dylanrussell/agent-router",
  "version": "2.2.0",
  "description": "Switch the models assigned to your opencode agents. Named stacks applied to agent frontmatter. Plugin + CLI.",
  "license": "MIT",
  "author": "Dylan Russell",
  "type": "module",
  "main": "./dist/plugin.js",
  "module": "./dist/plugin.js",
  "types": "./dist/plugin.d.ts",
  "exports": {
    ".": {
      "types": "./dist/plugin.d.ts",
      "import": "./dist/plugin.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    },
    "./cli": {
      "types": "./dist/cli.d.ts",
      "import": "./dist/cli.js"
    }
  },
  "bin": {
    "agent-router": "dist/cli.js"
  },
  "files": [
    "index.ts",
    "tui.ts",
    "dist",
    "assets/logo.svg",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "homepage": "https://github.com/dylanrussellmd/agent-router#readme",
  "bugs": "https://github.com/dylanrussellmd/agent-router/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/dylanrussellmd/agent-router.git"
  },
  "scripts": {
    "build": "tsup",
    "typecheck": "tsc --noEmit",
    "lint": "biome check src tests",
    "lint:fix": "biome check --write src tests",
    "format": "biome format --write src tests",
    "test": "vitest run --coverage",
    "test:unit": "vitest run tests/unit",
    "test:cli": "vitest run tests/cli",
    "test:plugin": "vitest run tests/plugin",
    "test:integration": "node scripts/smoke-v2.mjs",
    "test:quota": "node scripts/smoke-quota-v2.mjs",
    "test:quota-fallback": "ROUTER_PRODUCTION=1 node scripts/probe-quota-retry.mjs",
    "test:watch": "vitest",
    "version": "node scripts/sync-version.mjs && git add src/version.ts",
    "prepublishOnly": "npm run lint && npm run typecheck && npm run build && npm run test"
  },
  "peerDependencies": {
    "@opencode/plugin": "2.0.8"
  },
  "devDependencies": {
    "@biomejs/biome": "^1.9.4",
    "@opencode/plugin": "2.0.8",
    "@types/node": "^20.14.0",
    "@vitest/coverage-v8": "^4.1.11",
    "cac": "^6.7.14",
    "tsup": "^8.5.1",
    "tsx": "^4.21.0",
    "typescript": "^5.6.0",
    "vite": "^8.0.16",
    "vitest": "^4.1.11",
    "zod": "^4.0.0"
  },
  "engines": {
    "node": ">=20"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agents",
    "model-router",
    "llm-router"
  ],
  "publishConfig": {
    "access": "public"
  },
  "pnpm": {
    "overrides": {
      "uuid": ">=14.0.0",
      "vite": "^8.0.16",
      "esbuild": "^0.28.1",
      "postcss": "^8.5.23",
      "nanoid@3": "^3.3.18",
      "@opentelemetry/core": "^2.8.0"
    }
  }
}
